# تصحيحات 1.60 (القرار D247 — مراجعة فابل E، وD241 «لا نعلّم ما سننفيه»)
# الصيغة: قائمة C من القواميس {cid, match, op, data, ref, why} يطبّقها 07_أدوات_الفحص/بنك/apply.py
# يُقرأ البنك المصدر من المسار نفسه الذي يُمرَّر إلى apply.py (أو من المتغيّر BANK_SRC)، لأن المطابقة بنص السؤال.
import json, os, re, sys
HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.environ.get('BANK_SRC') or (sys.argv[1] if len(sys.argv) > 1 and sys.argv[1].endswith('.json') else os.path.join(HERE, '..', 'bank.json'))
B = json.load(open(SRC, encoding='utf-8'))
import copy
W = copy.deepcopy(B)                     # نسخة عمل تُحاكي ترتيب التطبيق في apply.py
ITEM = {x['id']: (cid, x) for cid, v in W.items() for x in v}
C = []
TOUCHED = set()
REF = 'D247 (مراجعة فابل E)'
KEYS = {'q': 'q', 'c': 'correct', 'w': 'wrongs', 'h': 'hint', 's': 'steps', 'ans': 'ans', 'tol': 'tol', 'cog': 'cog', 'lvl': 'level',
        'mis': 'misconception', 'kind': 'kind', 'svg': 'svg', 'type': 'type', 'ex': 'charter_exception', 'enrich': 'enrich', 'source': 'source'}
def _match(iid):
    cid, x = ITEM[iid]
    hits = [y for y in W[cid] if x['q'] in y['q']]
    assert len(hits) == 1, (iid, len(hits), 'رتّب التعديلات بحيث لا يكون نص السؤال جزءاً من سؤال آخر في المفهوم')
    return cid, x
def E(iid, why, ref=REF, **f):
    """تعديل بند: q, c(correct), w(wrongs), h(hint), s(steps), ans, tol, cog, lvl(level), mis(misconception), kind, svg, ex"""
    cid, x = _match(iid)
    data = {KEYS[k]: v for k, v in f.items()}
    if 'misconception' in data and x['type'] == 'choice' or data.get('type') == 'choice':
        wr = data.get('wrongs', x.get('wrongs', []))
        for k in data.get('misconception', {}): assert k in wr, (iid, k)
    C.append(dict(cid=cid, match=x['q'], op='set', data=data, ref=ref, why=why)); TOUCHED.add(iid)
    x.update(data)
    if x['type'] == 'num': x.pop('correct', None); x.pop('wrongs', None)
    else: x.pop('ans', None); x.pop('tol', None)
def S2(iid, step2, why='خطوة ثانية للحل (H1: steps ≥ 2)', ref=REF, **f):
    """إضافة خطوة ثانية إلى حل من خطوة واحدة (مع تعديلات اختيارية أخرى)."""
    cid, x = ITEM[iid]
    E(iid, why, ref, s=list(x['steps']) + [step2], **f)
def D(iid, why, ref=REF):
    cid, x = _match(iid)
    C.append(dict(cid=cid, match=x['q'], op='delete', data={}, ref=ref, why=why)); TOUCHED.add(iid)
    W[cid].remove(x)
def A(cid, why, ref=REF, **f):
    """إضافة بند جديد (يأخذ المعرّف التالي الحرّ): kind, type, q, c/w أو ans/tol, h, s, cog, lvl, mis"""
    data = {KEYS[k]: v for k, v in f.items()}
    assert {'kind', 'type', 'q', 'hint', 'steps', 'cog', 'level'} <= set(data), (cid, data.get('q'))
    C.append(dict(cid=cid, match='', op='add', data=data, ref=ref, why=why))
    n = max([int(y['id'].split('-')[1]) for y in W[cid]] + [0]) + 1
    W[cid].append(dict(id=f'{cid}-{n:02d}', **data))


